def main():
    p=json.loads((ROOT/'project.json').read_text(encoding='utf-8'))
    assert p['asset_review']['status']=='approved'
    p['pacing_direction']={'user_instruction':'proceed. be energetic, no slow motion in the video','speed':'real-time only','editing':'brisk story-driven cuts, playful reactions, 1-second endpoint holds','forbidden':['slow motion','speed ramps','time stretching','frame blending','long motionless beauty holds']}
    p['generation_route']={'status':'direct_seedance_authorized','authorization':'proceed. be energetic, no slow motion in the video','env_source':'../aifx-studio/.env','authorized_setting_names':['VOLC_ACCESS_KEY','VOLC_SECRET_KEY_RAW','VOLC_PROJECT_NAME','VOLC_ENDPOINT_SEEDANCE_25'],'credential_values_persisted':False,'supplied_photos_used_for_asset_generation_only':True}
    p['output_settings']={'duration':120,'ratio':'16:9','resolution':'720p','delivery_fps':30,'generate_audio':True,'watermark':False}
    p['prompt_library_sources']=['prompt-library/TEMPLATE.md','prompt-library/README.md','prompt-library/shots/scene-01/15_a-man-and-a-woman-sit-facing-each-other-at-a-table.md','prompt-library/sections/08_action-timing.md','prompt-library/sections/15_audio.md']
    script=[]
    for c,d in zip(p['chapters'],SCENES):
        shots=[]
        for start,end,action,camera,audio,ending in d['shots']:
            shots.append({'start':start,'end':end,'action':action,'camera':camera,'audio':audio,'end_state':ending})
        assert shots[0]['start']==0 and shots[-1]['end']==c['duration']
        assert all(a['end']==b['start'] for a,b in zip(shots,shots[1:]))
        active=[a for a in p['asset_list'] if a['tag'] in c['tagged_assets']]
        roles=[]
        for a in active:
            if a['category']=='character':
                role=a['description']+' Identity/material reference only. Sheet body and portrait views together describe ONE COMPLETE living character with an attached head and normal plush toy proportions. Never show detached heads, headless torsos, panels, studio backdrop or multiple clones. Preserve plush identity exactly; expressive embroidered faces may blink and speak.'
            elif a['category']=='environment':
                role=a['description']+' Landscape/material/geography reference only; adapt light to the timed sunset or night indicated here. Do not copy plate as a static photo. Cloud stars awaken only at the restoration beat.'
            else:
                role=a['description']+' Shape/material/face reference only. ONE continuous star; prop ownership changes only as timed. Never inflate to friend size.'
            roles.append(a['tag']+': '+role)
        timeline=[]
        for i,s in enumerate(shots,1):
            timeline.append(f"Shot {i} ({s['start']}s-{s['end']}s):\nACTION: {s['action']}\nCAMERA: {s['camera']}\nAUDIO / DIALOGUE: {s['audio']}\nEND STATE: {s['end_state']}")
        prompt='\n\n'.join([
         'SCENE CONTEXT\n'+c['scene_summary']+' This is an energetic, lovely friendship adventure for young viewers, carried by readable playful performances.',
         f"OUTPUT SETTINGS\n{c['duration']} seconds. 16:9, 720p. Soft 3D plush animation, tactile short velvet fur and embroidered facial features, warm pastel miniature world. Full generated character motion, normal-speed animation, lively and buoyant. REAL-TIME ONLY. Absolutely no slow motion, no speed ramp, no time stretch, no frame blending, no dreamy drifting action. Quick natural reactions and springy toy-scale movement. The gentle moments use normal-speed acting too.",
         'ACTIVE REFERENCES\n'+'\n'.join(roles),
         'LOCATION MAP / FIRST FRAME AND SPATIAL BLOCKING\n'+d['first']+' Keep complete heads attached to complete bodies. Exactly the five individual friends, no duplicated sheet views. No reference-sheet composition in the movie.',
         'FORMAT MODE / FRAMING\nExplicit story-driven hard cuts only at listed shot boundaries. No dissolves or slow-motion montage. Medium and wide coverage keep action and reactions readable; close-ups only for the timed important beats. Begin already in the described action and composition, no separate empty opening shot.',
         'OPTICS / CAMERA\nUse the focal lengths and movements per shot, camera at toy eye level unless the overhead circle or aerial geography calls for a height change. Moderate depth of field so faces and important props remain clear. Smooth brisk tracking, no wandering gimbal float, no fisheye, no unnecessary spin, no lens warping, no accidental focus hunts. All physical camera travel at normal speed.',
         'ACTION TIMING / SHOT SEQUENCE\n'+'\n\n'.join(timeline),
         'PHYSICS / PERFORMANCE\nPaws visibly contact the moss with quick soft plush compression and rebound. No moonwalking, slipping, impossible grips, growing fingers or stretched bodies. Cloth fibers follow brisk motion and settle promptly. The only magic is the floating ghost, living star and rainbow cushion. Rainbow flight is quick, joyful and safe, NOT suspended slow motion. Existing paws, wings and flippers touch naturally; no extra hands. Maintain lively blinking, short breaths, tiny ear twitches and postural motion during the final brief edit hold.',
         'LIGHTING\n'+d['light']+' Preserve pastel colors and gentle dimensional plush texture. No harsh flicker, horror lighting, blown-out faces or unrelated strobes.',
         'AUDIO\nNative generated synchronized English dialogue exactly as timed in the shot sequence. Bright warm character voices, distinct per speaker: cheerful laughing kitten @Mochi; brave slightly lower little tiger @Tiggy; curious chirpy chick @Pip; airy shy ghost @Bubbles; tender bright kitten @Lulu; tiny bell-like star when present. Warm lively narrator only where explicitly timed. A playful 116 BPM major-key pizzicato, glockenspiel, light ukulele and soft tap-percussion underscore, low under speech. Sunny cheerful adventure music throughout; no sleepy lullaby, sustained ambient drone or lyrics. Permitted layers: timed spoken lines, timed laughs and small gasps, soft footsteps/plush contact, light garden or cloud wind, specified magic/comedy effects and this cheerful score. This is the complete sound list; no additional narration, unrequested dialogue or loud scary sounds.',
         'IDENTITY / TEXT / SPEED LOCKS\nMochi circular cheek blush and laughing face stay distinct from Lulu flower cheeks and gray ear pads. Tiggy stays orange with black tiger markings; Pip stays yellow with an orange beak; Bubbles stays blue, tapered and legless, without hanging loops. No key rings, fabric tags, studio sheets, labels, extra figures, costumes, face swaps or anatomy changes. No written words anywhere, including constellations. No titles, subtitles, captions, credits, text cards, speech bubbles, logos or watermark. No slow motion under any name.',
         'POSITIVE CONSTRAINTS\nExactly five unique adorable complete friends, plus one living star only when the chapter links it. One cohesive soft plush visual style and stable garden geography. Every timed action is shown at normal real-time speed with energetic readable performance. Meaning conveyed by acting and spoken English, never typography. Timed shots span the entire clip; last state matches the next chapter. End without an end card.'
        ])
        # Do not refer to an unlinked star or sky as a provider asset.
        used=set(c['tagged_assets'])
        for a in p['asset_list']:
            if a['tag'] not in used:
                prompt=prompt.replace(a['tag'],a['name'])
        c.update(prompt=prompt,initial_prompt=prompt,prompt_status='final',shots=shots,resolution='720p',audio={'language':'English','native_generated':True,'music':'energetic playful 116 BPM','slow_motion':False},handoff={'first_frame':d['first'],'last_state':shots[-1]['end_state']})
        folder=ROOT/'chapters'/c['id']
        folder.mkdir(parents=True,exist_ok=True)
        (folder/'prompt-v01.txt').write_text(prompt+'\n',encoding='utf-8')
        script.append(f"{c['absolute_start']:03d}-{c['absolute_end']:03d}s | {c['title']}\n"+'\n'.join(f"  {s['start']}-{s['end']}s: {s['action']}\n  {s['audio']}" for s in shots))
    p['detailed_script']='\n\n'.join(script)
    p['master_prompt_raw']='Original 120-second Golden Star friendship adventure. Approved five plush identities, sunny garden, cloud sea and one golden star. Energetic normal-speed action with snappy reaction cuts. No slow motion, titles, subtitles or visible text. Native English voices, whimsical cheerful score and gentle timed Foley. 16:9 native 720p; delivery 30fps.'
    proposal=ROOT/'proposal-final-direction.json'
    proposal.write_text(json.dumps(p,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    (ROOT/'screenplay-final.md').write_text('# Final 120-second screenplay\n\n'+'\n\n'.join(script)+'\n',encoding='utf-8')
    for args in [('check',ROOT,'--from',proposal),('commit',ROOT,'--from',proposal,'--reason','Finalize energetic real-time eight-scene direction from approved assets'),('render-ready',ROOT),('export',ROOT)]:
        r=subprocess.run([sys.executable,str(HELPER),*map(str,args)],capture_output=True,text=True)
        if r.returncode:
            raise RuntimeError(r.stdout+r.stderr)
        if args[0]!='check':
            print(r.stdout)

if __name__=='__main__':
    main()
